    @Override public boolean onTouchEvent(MotionEvent e){float x=e.getX()/scale,y=e.getY()/scale;if(e.getAction()==MotionEvent.ACTION_DOWN){downX=x;downY=y;moved=false;return true;}if(e.getAction()==MotionEvent.ACTION_MOVE){if(Math.abs(x-downX)>15||Math.abs(y-downY)>15)moved=true;return true;}if(e.getAction()==MotionEvent.ACTION_UP){if(!moved)handleTap(x,y);return true;}return true;}
    private void handleTap(float x,float y){for(int i=hits.size()-1;i>=0;i--){Hit h=hits.get(i);if(!h.r.contains(x,y))continue;act(h,x,y);return;}}
    private void act(Hit h,float x,float y){String t=h.type;boolean ok=false;if("tab".equals(t)){tab=h.id;return;}if("tap".equals(t)){comboTaps++;lastTapAt=System.currentTimeMillis();boolean crit=rng.nextDouble()<.055;double a=s.tap(comboTaps,crit);fx.add(new Fx(x,y,(crit?"CRIT!  ":"+")+s.format(a),crit?ORANGE:GOLD));feedback(crit);return;}if("daily".equals(t)){int r=s.claimDaily();if(r>0){show(tr("Nagroda dzienna +","Daily reward +")+r+" ◆");feedback(true);}return;}if("missions".equals(t)){tab=4;missionMode=0;return;}if("achievements".equals(t)){tab=4;missionMode=3;missionPage=0;return;}if("event".equals(t)){if(s.eventType>=0){s.collectEvent();show(tr("Event odebrany!","Event collected!"));feedback(true);}return;}if("boss".equals(t)){if(!s.bossActive)ok=s.startBoss();else{double a=s.tap(Math.max(1,comboTaps),false);fx.add(new Fx(x,y,"-"+s.format(a)+" HP",RED));ok=true;}}else if("power".equals(t))ok=s.activatePowerTap();else if("buyMode".equals(t)){buyMode=h.id;return;}else if("building".equals(t)){int n=buyMode==0?1:buyMode==1?10:buyMode==2?25:buyMode==3?100:s.maxAffordableBuildingCount(h.id);ok=s.buyBuilding(h.id,n);}else if("hero".equals(t))ok=s.upgradeHero(h.id);else if("tech".equals(t))ok=s.buyTech(h.id);else if("mission".equals(t))ok=s.claimMission(h.id);else if("missionMode".equals(t)){missionMode=h.id;missionPage=0;return;}else if("shop".equals(t))ok=s.shopBuy(h.id);else if("buildPrev".equals(t)){buildPage=Math.max(0,buildPage-1);return;}else if("buildNext".equals(t)){buildPage++;return;}else if("heroPrev".equals(t)){heroPage=Math.max(0,heroPage-1);return;}else if("heroNext".equals(t)){heroPage++;return;}else if("techPrev".equals(t)){techPage=Math.max(0,techPage-1);return;}else if("techNext".equals(t)){techPage=Math.min(1,techPage+1);return;}else if("achPrev".equals(t)){missionPage=Math.max(0,missionPage-1);return;}else if("achNext".equals(t)){missionPage=Math.min(4,missionPage+1);return;}else if("offline".equals(t)){offlinePopup=false;return;}else if("tutorial".equals(t)){if(tutorialStep<3)tutorialStep++;else{s.tutorialSeen=true;s.save(getContext());}return;}else if("rebirth".equals(t)){long now=System.currentTimeMillis();if(s.availableLegacyStars()<=0)return;if(now<rebirthArmedUntil){ok=s.rebirth();rebirthArmedUntil=0;}else{rebirthArmedUntil=now+3500;show(tr("Dotknij ponownie, aby potwierdzić Odrodzenie","Tap again to confirm Rebirth"));return;}}else if("lang".equals(t)){String[] l={"pl","en","es","cs","ru","zh"};int ix=0;for(int i=0;i<l.length;i++)if(l[i].equals(s.language))ix=i;s.language=l[(ix+1)%l.length];s.save(getContext());return;}else if("sound".equals(t)){s.sound=!s.sound;return;}else if("haptic".equals(t)){s.haptics=!s.haptics;return;}else if("lowpower".equals(t)){s.lowPower=!s.lowPower;return;}else if("reset".equals(t)){long now=System.currentTimeMillis();if(now<resetArmedUntil){s.hardReset(getContext());show(tr("Zapis usunięty — uruchom grę ponownie","Save cleared — restart the game"));resetArmedUntil=0;}else{resetArmedUntil=now+3500;show(tr("Dotknij ponownie, aby USUNĄĆ zapis","Tap again to DELETE save"));}return;}if(ok){feedback(false);show(tr("Gotowe!","Done!"));}else show(tr("Jeszcze nie możesz tego zrobić","Not available yet"));}
    public boolean handleBack(){if(offlinePopup){offlinePopup=false;return true;}if(!s.tutorialSeen)return true;if(tab!=0){tab=0;return true;}return false;}

    private int readyMissions(){int n=0;for(int i=0;i<18;i++)if(s.missionReady(i))n++;return n;}
    private void show(String m){toast=m;toastUntil=System.currentTimeMillis()+1600;}
    private void feedback(boolean strong){if(s.sound&&tone!=null)try{tone.startTone(strong?ToneGenerator.TONE_PROP_ACK:ToneGenerator.TONE_PROP_BEEP,strong?80:35);}catch(Throwable ignored){}if(s.haptics&&vib!=null&&vib.hasVibrator())try{if(Build.VERSION.SDK_INT>=26)vib.vibrate(VibrationEffect.createOneShot(strong?55:22,strong?170:80));else vib.vibrate(strong?55:22);}catch(Throwable ignored){}}
    private String tr(String pl,String en){return ReleaseGameState.tr(s.language,pl,en,en,en,en,en);}
    private void panel(Canvas c,float x1,float y1,float x2,float y2,int fill,int stroke,float r){p.setShader(null);p.setStyle(Paint.Style.FILL);p.setColor(fill);c.drawRoundRect(new RectF(x1,y1,x2,y2),r,r,p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(2);p.setColor(stroke);c.drawRoundRect(new RectF(x1,y1,x2,y2),r,r,p);p.setStyle(Paint.Style.FILL);}
    private void button(Canvas c,float x1,float y1,float x2,float y2,String label,int fill,int color,boolean enabled){p.setColor(enabled?fill:Color.rgb(48,55,60));c.drawRoundRect(new RectF(x1,y1,x2,y2),9,9,p);if(enabled){p.setShader(new LinearGradient(0,y1,0,y2,Color.argb(80,255,255,255),Color.TRANSPARENT,Shader.TileMode.CLAMP));c.drawRoundRect(new RectF(x1+2,y1+2,x2-2,y1+(y2-y1)*.44f),8,8,p);p.setShader(null);}text(c,label,(x1+x2)/2,(y1+y2)/2+5,10,enabled?color:MUTED,Paint.Align.CENTER);}
    private void progress(Canvas c,float x1,float y1,float x2,float y2,float v,int col){v=Math.max(0,Math.min(1,v));p.setColor(Color.rgb(29,44,52));c.drawRoundRect(new RectF(x1,y1,x2,y2),7,7,p);if(v>0){p.setShader(new LinearGradient(x1,y1,x2,y2,light(col,1.14f),dark(col,.83f),Shader.TileMode.CLAMP));c.drawRoundRect(new RectF(x1,y1,x1+(x2-x1)*v,y2),7,7,p);p.setShader(null);}}
    private void pager(Canvas c,float bottom,int pages,int page,String prev,String next){if(pages<=1)return;float y=bottom-46;button(c,25,y,160,bottom-5,"‹",PANEL2,TEXT,page>0);button(c,560,y,695,bottom-5,"›",PANEL2,TEXT,page<pages-1);text(c,(page+1)+" / "+pages,360,y+27,10,MUTED,Paint.Align.CENTER);if(page>0)hits.add(new Hit(new RectF(20,y-5,165,bottom),prev,0));if(page<pages-1)hits.add(new Hit(new RectF(555,y-5,700,bottom),next,0));}
    private void wrap(Canvas c,String str,float x,float y,float max,float size,int color){String[] ws=str.split(" ");String line="";int row=0;tp.setTextSize(size);for(String a:ws){String n=line.isEmpty()?a:line+" "+a;if(tp.measureText(n)>max&&!line.isEmpty()){text(c,line,x,y+row*(size+6),size,color,Paint.Align.CENTER);row++;line=a;}else line=n;}if(!line.isEmpty())text(c,line,x,y+row*(size+6),size,color,Paint.Align.CENTER);}
    private void text(Canvas c,String text,float x,float y,float size,int color,Paint.Align align){tp.setShader(null);tp.setStyle(Paint.Style.FILL);tp.setTextSize(size);tp.setTextAlign(align);tp.setColor(color);tp.setTypeface(Typeface.create("sans-serif-condensed",Typeface.BOLD));c.drawText(text,x,y,tp);}
    private int dark(int c,float f){return Color.rgb(clamp((int)(Color.red(c)*f)),clamp((int)(Color.green(c)*f)),clamp((int)(Color.blue(c)*f)));}
    private int light(int c,float f){return Color.rgb(clamp((int)(Color.red(c)*f)),clamp((int)(Color.green(c)*f)),clamp((int)(Color.blue(c)*f)));}
    private int clamp(int v){return Math.max(0,Math.min(255,v));}
